data.rationale:
Test one Mother-authored arithmetic rewrite on the only valid measured base. It cancels the target-mass factor from acceleration and uses rsqrtf; this is a hypothesis, not a confirmed speedup. Keep launch.json unchanged. Complete files:
src/nbody_kernel.cu:
struct Particle { float x,y,z,vx,vy,vz,mass; };
extern "C" __global__ void nbody_step_naive(const Particle* in, Particle* out, int n, float dt) {
  int i=blockIdx.x*blockDim.x+threadIdx.x;
  if(i>=n) return;
  const Particle pi=in[i];
  float ax=0.0f, ay=0.0f, az=0.0f;
  for(int j=0;j<n;++j) {
    if(i==j) continue;
    const Particle pj=in[j];
    float dx=pj.x-pi.x, dy=pj.y-pi.y, dz=pj.z-pi.z;
    float r2=dx*dx+dy*dy+dz*dz+0.001f;
    float invr=rsqrtf(r2);
    float s=pj.mass*invr*invr*invr;
    ax+=s*dx; ay+=s*dy; az+=s*dz;
  }
  Particle p=pi;
  p.vx+=ax*dt; p.vy+=ay*dt; p.vz+=az*dt;
  p.x+=p.vx*dt; p.y+=p.vy*dt; p.z+=p.vz*dt;
  out[i]=p;
}
